// The FIRST loop runs before JIT tiering settles and observes a small
// per-call overhead; after warmup the span path is byte-identical to
// zero. The Split path still allocates per call, so it fails the second
// (warmed) measurement — exactly the lesson.
ReadOnlySpan<char> s = "9,10".AsSpan();
for (int i = 0; i < 200; i++) Solution.ParsePair(s);   // warmup
long before = GC.GetAllocatedBytesForCurrentThread();
for (int i = 0; i < 100; i++) Solution.ParsePair(s);
long after = GC.GetAllocatedBytesForCurrentThread();
Cj.True(after - before <= 96, $"100 warmed parses allocated {after - before} bytes (must be ~0)");
